// Generates functions/_shared/solutions.generated.ts — a server-only map of
// lessonId → solution.js text. The Pages Function at
// /api/lesson-solution/[id] reads this map and gates it to admin/teacher.
//
// solution.js files are intentionally excluded from the static client bundle
// (see lib/lessons.ts), so this generated file is the only path by which the
// reference answer ever leaves the repo.

import fs from 'fs/promises';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '..');
const lessonsDir = path.join(root, 'lessons');
const outPath = path.join(root, 'functions', '_shared', 'solutions.generated.ts');

const entries = await fs.readdir(lessonsDir, { withFileTypes: true });
const dirs = entries.filter((e) => e.isDirectory()).map((e) => e.name);

const map = {};
for (const id of dirs) {
  const file = path.join(lessonsDir, id, 'solution.js');
  try {
    map[id] = await fs.readFile(file, 'utf8');
  } catch {
    /* no solution for this lesson — skip */
  }
}

const sortedIds = Object.keys(map).sort();
const body =
  '// AUTO-GENERATED by scripts/generate-solutions.mjs — do not edit.\n' +
  '// Source: lessons/<id>/solution.js. Regenerated on every build.\n\n' +
  'export const SOLUTIONS: Record<string, string> = {\n' +
  sortedIds
    .map((id) => `  ${JSON.stringify(id)}: ${JSON.stringify(map[id])},`)
    .join('\n') +
  '\n};\n';

await fs.mkdir(path.dirname(outPath), { recursive: true });
await fs.writeFile(outPath, body);
console.log(
  `[generate-solutions] wrote ${sortedIds.length} solution(s) → functions/_shared/solutions.generated.ts`,
);
